PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?country
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Cupid_the_Cowpuncher> 
    <http://dbpedia.org/resource/Hashimura_Togo>
  }
  OPTIONAL { ?film dbp:country ?country . }
}
LIMIT 100

